}
```

输出 JSON 格式契约（score 必须为 0 或 1）：
{
  "dim_1_1_intent": {
    "score": 1,
    "pass": true,
    "evidence_analysis": "推导过程：分析用户属于什么意图，Agent 实际调用了哪些工具，话术怎么回复的",
    "reason": "100字以内大白话结论"
  },
  "dim_2_1_clarification": {
    "score": 1,
    "pass": true,
    "evidence_analysis": "推导过程说明（若非澄清置 null）",
    "reason": "100字以内大白话结论"
  },
  "dim_2_2_repetition": null,
  "dim_6_1_boundary": {
